// mep's Rust language server, analysis half: see rust_lsp.h.
//
// Generated by tools/new_language.py as a skeleton: completion offers the
// words of the document and everything else answers "nothing". Replace it
// piece by piece -- a parser whose errors are the language's own, a scope
// analysis, then the features over them (nix_lsp.cpp is the worked example).
#include "rust_lsp.h"

#include <algorithm>
#include <cctype>
#include <set>

#include "rust_format.h"

class RustLspDocument {
public:
    std::vector<std::string> lines;
};

namespace {

bool IsWordChar(char c) { return std::isalnum(static_cast<unsigned char>(c)) || c == '_'; }

}  // namespace

std::shared_ptr<const RustLspDocument> RustLspAnalyze(const std::vector<std::string> &lines) {
    auto doc = std::make_shared<RustLspDocument>();
    doc->lines = lines;
    return doc;
}

std::vector<RustLspDiagnostic> RustLspDiagnostics(const RustLspDocument &doc) {
    (void)doc;
    return {};
}

std::string RustLspFormatDiagnostic(const std::string &path, const RustLspDiagnostic &d) {
    const char *sev = d.severity == RustLspSeverity::Error         ? "error"
                      : d.severity == RustLspSeverity::Warning     ? "warning"
                      : d.severity == RustLspSeverity::Information ? "info"
                                                                     : "hint";
    return path + ":" + std::to_string(d.range.line + 1) + ":" + std::to_string(d.range.col + 1) + ": " + sev + ": " +
           d.message + " [" + d.code + "]";
}

bool RustLspDiagnosticFails(const RustLspDiagnostic &d) {
    return d.severity == RustLspSeverity::Error || d.severity == RustLspSeverity::Warning;
}

std::vector<RustLspCompletionItem> RustLspCompletions(const RustLspDocument &doc, int line, int col) {
    std::vector<RustLspCompletionItem> out;
    if (line < 0 || static_cast<size_t>(line) >= doc.lines.size()) return out;
    const std::string &cur = doc.lines[static_cast<size_t>(line)];
    col = std::max(0, std::min(col, static_cast<int>(cur.size())));
    int start = col;
    while (start > 0 && IsWordChar(cur[static_cast<size_t>(start - 1)])) start--;
    const std::string prefix = cur.substr(static_cast<size_t>(start), static_cast<size_t>(col - start));
    std::set<std::string> words;
    for (size_t li = 0; li < doc.lines.size(); li++) {
        const std::string &l = doc.lines[li];
        for (size_t i = 0; i < l.size();) {
            if (!IsWordChar(l[i]) || std::isdigit(static_cast<unsigned char>(l[i]))) {
                i++;
                continue;
            }
            size_t j = i;
            while (j < l.size() && IsWordChar(l[j])) j++;
            const bool at_cursor = li == static_cast<size_t>(line) && static_cast<int>(i) == start;
            if (!at_cursor && l.compare(i, prefix.size(), prefix) == 0) words.insert(l.substr(i, j - i));
            i = j;
        }
    }
    for (const std::string &w : words) {
        RustLspCompletionItem it;
        it.label = w;
        it.insert_text = w;
        it.kind = RustLspKind::Text;
        it.replace_start = start;
        it.replace_end = col;
        out.push_back(it);
    }
    return out;
}

